import{c as o,Q as a,j as t,m as r}from"./chunks/framework.BPKcPtvA.js";const i="/screenshots/login-activation.png",l="/screenshots/booth-login-window.png",u=JSON.parse('{"title":"インストール","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md","lastUpdated":1786518246000}'),n={name:"guide/installation.md"};function s(c,e,g,d,h,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="インストール" tabindex="-1">インストール <a class="header-anchor" href="#インストール" aria-label="Permalink to &quot;インストール&quot;">​</a></h1><p>BOOTH Package Linker は <strong>Windows 10 / 11 (x64)</strong> で動く Electron デスクトップアプリです。 macOS / Linux 用ビルドは提供していません (BOOTH の Web 認証まわりが Windows でしか実機検証されていないため)。</p><h2 id="ダウンロード" tabindex="-1">ダウンロード <a class="header-anchor" href="#ダウンロード" aria-label="Permalink to &quot;ダウンロード&quot;">​</a></h2><p>GitHub Releases から最新のインストーラを取得します。3 種類を配布していますが、 迷ったら一番上の <strong>インストーラ (Setup)</strong> を選べば大丈夫です。</p><ul><li><strong>インストーラ (推奨)</strong>: <code>BOOTH.Package.Linker-x.y.z-Setup.exe</code> — 実行するとインストールされ、スタートメニューに登録されます</li><li><strong>ポータブル</strong>: <code>BOOTH.Package.Linker-x.y.z-portable.exe</code> — インストール不要。置いた場所からそのまま起動します</li><li><strong>ZIP</strong>: <code>BOOTH.Package.Linker-x.y.z-win.zip</code> — 好きなフォルダに展開して、中の exe を起動します</li></ul><p>(<code>x.y.z</code> はバージョン番号です)</p><p><a href="https://github.com/ChanyaVRC/booth-package-linker-releases/releases" target="_blank" rel="noreferrer">最新リリースを見る</a> →</p><h2 id="初回起動" tabindex="-1">初回起動 <a class="header-anchor" href="#初回起動" aria-label="Permalink to &quot;初回起動&quot;">​</a></h2><ol><li>インストーラを実行 → スタートメニューから「BOOTH Package Linker」を起動。</li><li>ライセンスが未認証の場合は、アクティベート画面で次のどちらかを選びます。 <ul><li><strong>BOOTH アカウントで認証 (かんたん)</strong>: このアプリを BOOTH で購入 / ギフトで受け取っていれば、利用できる BOOTH ログイン状態を使って認証できます。自動で認証されなかったときは <strong>「BOOTH アカウントで認証」</strong> を押してください (詳しくは <a href="#booth-ログイン">BOOTH ログイン</a>)。</li><li><strong>ライセンスキーで認証</strong>: お渡ししたライセンスキーを入力します。配布物に <code>license.key</code> が同梱されている場合は、入力なしで自動アクティベートされます (zip を展開して exe を起動するだけ)。</li><li>どちらの場合も、初回の認証には <strong>ネットワーク接続が必要</strong> です。認証後は、最後にサーバーで有効性を確認できた時点から <strong>14 日間</strong>、オフラインでも起動できます (詳細は <a href="/guide/settings#ライセンス">設定 &gt; ライセンス</a> 参照)。</li></ul></li><li>画面左端の歯車アイコン <strong>「設定」</strong> を開いて、<strong>ダウンロード先フォルダ</strong> を確認・変更します。 <ul><li>デフォルト: <code>&lt;Documents&gt;/booth-package-linker/</code></li></ul></li><li>ライセンスの確認が終わると、ライブラリ取得などのバックグラウンド処理が始まります。処理中もアプリは操作できます。 <ul><li>「起動時にライブラリを自動取得する」はデフォルトで ON です。既存購入アイテムは、BOOTH への取得間隔をはさみながら順次取り込まれます。</li><li>進み具合の確認や中止は <a href="/guide/background-tasks#どこから確認する">バックグラウンドタスク</a> から行えます。</li></ul></li></ol><h2 id="ブラウザ拡張は不要" tabindex="-1">ブラウザ拡張は不要 <a class="header-anchor" href="#ブラウザ拡張は不要" aria-label="Permalink to &quot;ブラウザ拡張は不要&quot;">​</a></h2><p>BOOTH ページの「BOOTH Library Manager で DL」から直接アプリへ送れるため、 <strong>ブラウザ拡張を入れる必要はありません</strong>。</p><p>「…」メニューに <strong>「このアプリで開く設定なし」</strong> と表示されている場合は、 その項目をクリックして登録します。通常表示では画面右上、サイドバー表示では 左側アイコンバー下部の「…」から開けます。別の場所にあるアプリがすでに登録されて いても、起動しただけではその関連付けを上書きしません。</p><p>登録後、BOOTH で初めてリンクをクリックしたときに「このリンクで <code>BOOTH Package Linker</code> を開きますか?」と確認されたら、開くことを許可してください。</p><h2 id="booth-ログイン" tabindex="-1">BOOTH ログイン <a class="header-anchor" href="#booth-ログイン" aria-label="Permalink to &quot;BOOTH ログイン&quot;">​</a></h2><p>このアプリは、ライブラリの取得やライセンスの自動認証のために <strong>あなたの BOOTH のログイン状態</strong> を使います。方法は 2 通りあり、利用できる方が自動で選ばれます。</p><h3 id="_1-ブラウザのログインを利用する" tabindex="-1">1. ブラウザのログインを利用する <a class="header-anchor" href="#_1-ブラウザのログインを利用する" aria-label="Permalink to &quot;1. ブラウザのログインを利用する&quot;">​</a></h3><p><strong>普段お使いのブラウザで <code>https://accounts.booth.pm/</code> にログイン済み</strong> で、そのログイン状態をアプリが利用できる場合は、追加操作は不要です。</p><p>対応ブラウザ:</p><ul><li>Chromium: Chrome / Edge / Brave / Vivaldi / Opera / Opera GX / Yandex / Arc</li><li>Mozilla 系: Firefox / Zen / Floorp / LibreWolf / Waterfox</li></ul><p>インストールされている対応ブラウザから、読み取れるログイン状態を利用します。 読み取れない場合は「2. アプリの中でログインする」を使ってください。</p><div class="warning custom-block"><p class="custom-block-title">Chrome / Edge など Chromium 系の最近のバージョンについて</p><p>Chrome や Edge をはじめとする Chromium 系ブラウザは、最近のバージョンでセキュリティの仕様が変わり、<strong>アプリからログイン状態を読み取れなくなっています</strong>。これらのブラウザをお使いの場合は、下の <strong>「2. アプリの中でログインする」</strong> をご利用ください（Firefox など Mozilla 系は引き続き利用できます）。</p></div><h3 id="_2-アプリの中でログインする" tabindex="-1">2. アプリの中でログインする <a class="header-anchor" href="#_2-アプリの中でログインする" aria-label="Permalink to &quot;2. アプリの中でログインする&quot;">​</a></h3><p>お使いのブラウザの種類やバージョン（特に上記の最近の Chrome / Edge など）によっては、アプリがブラウザのログイン状態を読み取れません。その場合は <strong>アプリの中で直接 BOOTH にログイン</strong> できます。入口は 2 か所です。</p><ul><li>ライセンス認証画面の <strong>「BOOTH アカウントで認証」</strong> ボタン</li></ul><p><img src="'+i+'" alt="ライセンス認証画面 — ライセンスキー入力欄と「BOOTH アカウントで認証」ボタン"></p><ul><li>ライブラリの取得中に「BOOTH ログインが必要です」と表示されたときの <strong>「ログイン」</strong> ボタン</li></ul><p>どちらからでも、アプリの中に BOOTH のログイン画面が開きます。いつも通り BOOTH にログインしてください。</p><p><img src="'+l+'" alt="アプリの中で開く BOOTH のログイン画面（pixiv アカウントでログイン）"></p><p>ログインが終わるとウィンドウは自動で閉じます。ログイン状態は保存され、 BOOTH 側で期限切れになるまでは次回の起動でも利用されます。</p><h2 id="アンインストール" tabindex="-1">アンインストール <a class="header-anchor" href="#アンインストール" aria-label="Permalink to &quot;アンインストール&quot;">​</a></h2><ul><li>Windows の「アプリと機能」から <strong>BOOTH Package Linker</strong> を選んで削除。</li><li>ダウンロード済みファイルは別フォルダ (<code>&lt;Documents&gt;/booth-package-linker/</code>) にあるので、削除したい場合は手動で。</li><li>設定とライブラリのデータは <code>%APPDATA%\\BOOTH Package Linker\\</code> 配下にあります。</li></ul>',31)])])}const m=o(n,[["render",s]]);export{u as __pageData,m as default};
